// Generated by bildr from .bildr/datasources/catalog.json. Editing this file detaches it from the editor.
import { describe, expect, it } from 'vitest'
import { CatalogFailure, remoteFailed } from '../../shared/domain/catalog/errors'
import { product } from '../../shared/domain/catalog/use-cases/product'
import { fakeCatalogRepository } from './fake-repository'

describe('product', () => {
  it('returns what the API answers', async () => {
    const repository = fakeCatalogRepository({ product: async () => ({
      id: 1,
      name: 'name 1',
      price: 1.5,
      inStock: true,
      createdAt: '2024-01-02T03:04:05.000Z',
      note: 'note 1',
      categories: [
        {
          id: 1,
          name: 'name 1'
        }
      ]
    }) })
    const result = await product({ catalog: repository })({
      id: 1
    })
    expect(result).toEqual({ ok: true, value: {
      id: 1,
      name: 'name 1',
      price: 1.5,
      inStock: true,
      createdAt: '2024-01-02T03:04:05.000Z',
      note: 'note 1',
      categories: [
        {
          id: 1,
          name: 'name 1'
        }
      ]
    } })
  })

  it('returns a failure of the API as a remote_failed error', async () => {
    const repository = fakeCatalogRepository({
      product: async () => {
        throw new CatalogFailure(remoteFailed(503, 'answered 503'))
      }
    })
    const result = await product({ catalog: repository })({
      id: 1
    })
    expect(result).toEqual({ ok: false, error: expect.objectContaining({ type: 'remote_failed', status: 503 }) })
  })

  it('refuses an input that is not valid, without calling the API', async () => {
    const repository = fakeCatalogRepository()
    const result = await product({ catalog: repository })({ id: 'wrong' } as never)
    expect(result).toEqual({ ok: false, error: expect.objectContaining({ type: 'invalid_input' }) })
  })
})
